      }
    }
  }

  // --- Draw: Evocation ---
  /** @param {CanvasRenderingContext2D} ctx */
  function drawEvocation(ctx) {
    if (!_evocationChannels.size || typeof getPosition !== "function") return;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    const now = getFxTime();
